/* Host cost test for a REAL stage room (perf rule: reproduce offline first).
 *
 * The synthetic table below scales the object count; the fixture mode loads the
 * object mix, spawns and terrain of one converted room (default: stage 0 map 1,
 * the intro stage's second room - the "lots of objects" slowdown report) and
 * reports what one frame of objects_update() actually does there, with a
 * per-object breakdown so the expensive type is named.
 *
 * Fixture generated by: tools/emit_host_fixture.py 0 1
 * Run:                 tools/run_host_tests.sh
 */
#include <genesis.h>
#include <stdio.h>
#include <string.h>

#include "stage_data.h"
#include "object.h"
#include "player.h"
#include "stage.h"
#include "resources.h"
#include "fixtures/stage0_map1.h"

extern u32 host_terrain_calls;
extern u32 host_spr_calls;
extern u16 host_sprites_visible(void);
extern void host_sprites_reset(void);
extern u32 host_pred_calls;
extern u32 host_obj_work[];
extern u32 host_obj_terr[];
extern u32 host_obj_spr[];
extern void host_terrain_fill(u8 value);
extern void host_terrain_set(const unsigned char *src, s16 w, s16 h);
extern u16 host_random_value;
extern u32 host_obj_work[];

static ObjectDef defs[8];
static ObjectSpawn spawns[OBJECT_MAX];
static StageBgInfo bg_info[1];

/* ---- synthetic scaling test (object count) ---------------------------- */
static void build_stage(u8 objects)
{
    memset(defs, 0, sizeof defs);
    defs[0].spr = &object_energy_pill_small_sprite;
    defs[0].type = 7;
    defs[0].frames = 2;
    defs[0].frame_t = 6;
    defs[0].w = 10;
    defs[0].h = 10;
    defs[0].anim_auto = 1;
    for (u8 i = 0; i < objects; i++) {
        spawns[i].def = 0;
        spawns[i].map = 0;
        spawns[i].x = (s16)(40 + i * 16);
        spawns[i].y = 100;
    }
    static StageDef stage;
    memset(&stage, 0, sizeof stage);
    stage.map_count = 1;
    stage.map_w = 200;
    stage.map_h = 14;
    stage.tile = 16;
    stage.terrain = NULL;
    stage.object_defs = defs;
    stage.object_def_count = 1;
    stage.object_spawns = spawns;
    stage.object_spawn_count = objects;
    stage.bg_info = bg_info;
    stage_def = &stage;
    stage_current_map = 0;
    camera.x = 0;
    camera.y = 0;
}

static void reset_counters(void)
{
    host_terrain_calls = 0;
    host_spr_calls = 0;
    host_pred_calls = 0;
    for (u8 i = 0; i < OBJECT_MAX; i++) {
        host_obj_work[i] = 0;
        host_obj_terr[i] = 0;
        host_obj_spr[i] = 0;
    }
}

static void run_scaling(void)
{
    host_terrain_fill(TERRAIN_UNBLOCKED);
    player.x = 8;
    player.y = 96;
    player.hp = 28;

    printf("objects on screen | pred/frame | terrain/frame | sprite calls/frame"
           " | est. subticks\n");
    u8 worst = 0;
    for (u8 n = 2; n <= 14; n += 4) {
        build_stage(n);
        objects_reset();
        reset_counters();
        enum { FRAMES = 60 };
        for (u16 f = 0; f < FRAMES; f++) objects_update();
        const u32 pred = host_pred_calls / FRAMES;
        const u32 terr = host_terrain_calls / FRAMES;
        const u32 spr = host_spr_calls / FRAMES;
        const u32 work = pred + terr + spr;
        printf("%17u | %10u | %13u | %18u | %12u\n", n, pred, terr, spr,
               38 + (work * 36) / 10);
        if (pred > n) worst = 1;
        if (terr > (u32)n + 2 || spr > (u32)n * 2 + 4) worst = 1;
    }
    if (worst) {
        printf("\nFAIL: type predicates are answered more than once per object "
               "per frame (the flag cache regressed)\n");
        exit(1);
    }
    printf("\nOK: predicates are answered once per object per frame\n");
}

/* ---- fixture test (a real room) --------------------------------------- */
static void build_fixture(void)
{
    memset(defs, 0, sizeof defs);
    for (u8 i = 0; i < FX_DEF_COUNT; i++) {
        defs[i].type = fx_defs[i].type;
        defs[i].frames = fx_defs[i].frames;
        defs[i].frame_t = fx_defs[i].frame_t;
        defs[i].w = fx_defs[i].w;
        defs[i].h = fx_defs[i].h;
        defs[i].speed = (u8)fx_defs[i].speed;
        defs[i].timer = fx_defs[i].timer;
        defs[i].limit = fx_defs[i].limit;
        defs[i].anim_auto = fx_defs[i].anim_auto;
        defs[i].anim_loop = fx_defs[i].anim_loop;
        defs[i].spr = &object_energy_pill_small_sprite;   /* dummy art */
    }
    for (u8 i = 0; i < FX_SPAWN_COUNT; i++) {
        spawns[i].def = fx_spawns[i].def;
        spawns[i].map = 0;                 /* the fixture is one map */
        spawns[i].x = fx_spawns[i].x;
        spawns[i].y = fx_spawns[i].y;
    }
    static StageDef stage;
    memset(&stage, 0, sizeof stage);
    stage.map_count = 1;
    stage.map_w = FX_MAP_W;
    stage.map_h = FX_MAP_H;
    stage.tile = 16;
    stage.terrain = NULL;
    stage.object_defs = defs;
    stage.object_def_count = FX_DEF_COUNT;
    stage.object_spawns = spawns;
    stage.object_spawn_count = FX_SPAWN_COUNT;
    stage.bg_info = bg_info;
    stage_def = &stage;
    stage_current_map = 0;
    host_terrain_set(fx_terrain, FX_MAP_W, FX_MAP_H);
}

static void run_fixture(void)
{
    /* the pill cluster of stage 0 map 1 sits at x = 592..720, the fall blocks
     * right of it: put the camera so they are all on screen, with the player
     * standing on the floor of that room */
    const s16 cams[] = { 480, 560, 640, 720 };
    printf("\nstage 0 map 1 (%d spawns, terrain %dx%d)\n",
           FX_SPAWN_COUNT, FX_MAP_W, FX_MAP_H);
    printf("camera | on screen | work/frame | est. subticks\n");
    u32 worst_work = 0;
    s16 worst_cam = 0;
    for (u8 c = 0; c < sizeof cams / sizeof cams[0]; c++) {
        build_fixture();
        camera.x = cams[c];
        camera.y = 0;
        player.x = (s16)(cams[c] + 80);
        player.y = 160;
        player.hp = 28;
        objects_reset();
        reset_counters();
        enum { FRAMES = 60 };
        for (u16 f = 0; f < FRAMES; f++) objects_update();
        u8 on_screen = 0;
        for (u8 i = 0; i < FX_SPAWN_COUNT; i++) {
            const s16 sx = (s16)(spawns[i].x - camera.x);
            if (sx + 32 > 0 && sx < 320) on_screen++;
        }
        const u32 work = (host_pred_calls + host_terrain_calls +
                          host_spr_calls) / FRAMES;
        printf("%6d | %9u | %10u | %12u\n", cams[c], on_screen, work,
               38 + (work * 36) / 10);
        if (work > worst_work) { worst_work = work; worst_cam = cams[c]; }
    }

    /* A resting room must be cheap: the objects' gravity probe is skipped once
     * they are found resting on static terrain (see objects_update). Before
     * that cache the same measurement was 113 work units per frame here. */
    if (worst_work > 20) {
        printf("\nFAIL: the fixture room asks for %u work units per frame "
               "(resting objects should probe the floor once, not every "
               "frame)\n", worst_work);
        exit(1);
    }

    /* per-object breakdown at the worst camera */
    build_fixture();
    camera.x = worst_cam;
    player.x = (s16)(worst_cam + 80);
    player.y = 160;
    objects_reset();
    reset_counters();
    enum { FRAMES2 = 60 };
    for (u16 f = 0; f < FRAMES2; f++) objects_update();
    printf("\nworst camera %d: per-object work per frame (top 6)\n", worst_cam);
    for (u8 rank = 0; rank < 6; rank++) {
        u8 best = 0xFF;
        u32 best_w = 0;
        for (u8 i = 0; i < FX_SPAWN_COUNT; i++) {
            const u32 w = host_obj_work[i];
            if (w > best_w) { best_w = w; best = i; }
        }
        if (best == 0xFF || !best_w) break;
        const u8 typ = fx_defs[spawns[best].def].type;
        printf("  #%2u type %2u %-28s x=%4d  %3u work/frame "
               "(terrain %u, sprite %u)\n",
               best, typ, fx_defs[spawns[best].def].name, spawns[best].x,
               best_w / FRAMES2, host_obj_terr[best] / FRAMES2,
               host_obj_spr[best] / FRAMES2);
        host_obj_work[best] = 0;
    }
}

/* ---- dropped items must fall ----------------------------------------- *
 * Report 2026-10-25: enemy drops hung in the air. Cause: objects_drop_item()
 * filled the object by hand, so `flags` (which carries the gravity answer) and
 * the resting-cache stayed 0. This spawns a drop in mid-air over open space and
 * asserts it descends. */
extern s16 host_obj_y(u8 i);
extern u8 host_obj_flags(u8 i);
extern u8 host_obj_count(void);

static void run_drops(void)
{
    build_stage(0);                       /* one pill def, no spawns */
    host_terrain_fill(TERRAIN_UNBLOCKED); /* nothing to land on */
    objects_reset();
    host_random_value = 70;               /* forces a small weapon pill */
    objects_drop_item(80, 40, FALSE);
    if (!host_obj_count()) {
        printf("\nFAIL: no drop was spawned\n");
        exit(1);
    }
    const s16 y0 = host_obj_y(0);
    const u8 flags = host_obj_flags(0);
    for (u16 f = 0; f < 20; f++) objects_update();
    const s16 y1 = host_obj_y(0);
    printf("\ndropped item: y %d -> %d, flags 0x%02X%s\n", y0, y1, flags,
           (y1 > y0) ? " (falls)" : " (HUNG IN THE AIR)");
    if (!(flags & 0x02) || y1 <= y0) {
        printf("FAIL: a dropped item must carry the gravity flag and fall\n");
        exit(1);
    }
}

/* The in-game menu hides every sprite on open and shows them again on close
 * (menu.c stage_sprites_visible). objects_update() keeps a per-object cache of
 * the visibility it last sent and only talks to the sprite when it changes, so
 * "show everything" on close made every OFF-SCREEN object visible for good: they
 * stayed at their stale position, fixed on screen while the room scrolled
 * (items_after_menu.png, 2026-10-26). After a menu round trip the set of visible
 * sprites must be the one from before the menu. */
static void run_menu_visibility(void)
{
    host_sprites_reset();
    build_fixture();
    camera.x = 480;                      /* part of the room is off screen */
    camera.y = 0;
    player.x = 560;
    player.y = 160;
    player.hp = 28;
    objects_reset();
    for (u16 f = 0; f < 10; f++) objects_update();
    const u16 before = host_sprites_visible();

    objects_set_visible(FALSE);          /* menu opens */
    objects_set_visible(TRUE);           /* menu closes */
    for (u16 f = 0; f < 3; f++) objects_update();
    const u16 after = host_sprites_visible();

    printf("\nmenu round trip: visible sprites %u -> %u%s\n", before, after,
           after == before ? "" : "   (OFF-SCREEN OBJECTS SHOWN)");
    if (after != before) {
        printf("FAIL: closing the menu must restore the sprites that were "
               "visible, not show every object\n");
        exit(1);
    }
}

int main(int argc, char **argv)
{
    if (argc > 1 && strcmp(argv[1], "--fixture") == 0) {
        run_fixture();
        run_drops();
        run_menu_visibility();
        return 0;
    }
    run_scaling();
    run_fixture();
    run_drops();
    run_menu_visibility();
    return 0;
}
